contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address sender, address other, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint256 beforeSender = c.balances(sender); if (__ESBMC_reverted()) return;
        uint256 beforeOther = c.balances(other); if (__ESBMC_reverted()) return;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 afterSender = c.balances(sender); if (__ESBMC_reverted()) return;
        uint256 afterOther = c.balances(other); if (__ESBMC_reverted()) return;

        assert(afterSender == beforeSender || other == sender || afterOther == beforeOther);
    }

    receive() external payable {}
}

