        try c.balances(sender) returns (uint256 __r) { afterSender = __r; } catch { return; }
        uint256 afterOther;
        try c.balances(other) returns (uint256 __r) { afterOther = __r; } catch { return; }
        assertTrue(afterSender == beforeSender || other == sender || afterOther == beforeOther);
